{
  "summary": "Implement triage script that filters ERROR lines, extracts signatures by removing variable key=value pairs, counts occurrences, and outputs in 'COUNT signature' format",
  "files": [
    {
      "path": "scripts/triage.sh",
      "content": "#!/usr/bin/env bash\nset -euo pipefail\n\nlog_file=\"$1\"\n\n# Filter ERROR lines, extract message, remove variable key=value pairs, count signatures\ngrep \" ERROR \" \"$log_file\" | \\\n  sed 's/^[^ ]* ERROR //' | \\\n  sed 's/ [a-zA-Z_][a-zA-Z0-9_]*=[^ ]*//g' | \\\n  sed 's/^ *//;s/ *$//' | \\\n  sort | uniq -c | \\\n  sed 's/^[ ]*//'\n"
    }
  ]
}
